<?php
require_once __DIR__.'/config.php';require_role(['admin']);$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
if($action==='create'){$u=trim($_POST['username']??'');$n=trim($_POST['full_name']??'');$p=(string)($_POST['password']??'');$role=$_POST['role']??'viewer';if(!preg_match('/^[A-Za-z0-9_.-]{3,60}$/',$u)||$n===''||strlen($p)<12||!in_array($role,['admin','hr','viewer'],true))$error='Check username, full name, role, and password (12+ characters).';else{try{$hash=password_hash($p,PASSWORD_DEFAULT);$s=$db->prepare('INSERT INTO users(username,password_hash,full_name,role) VALUES(?,?,?,?)');$s->bind_param('ssss',$u,$hash,$n,$role);$s->execute();audit($db,'USER_CREATED','user',(string)$db->insert_id,'Created user '.$u.' with role '.$role);$message='User created.';}catch(Throwable $e){$error='Could not create user. The username may already exist.';}}}
if($action==='toggle'){$id=(int)($_POST['id']??0);if($id===(int)$_SESSION['user_id'])$error='You cannot deactivate your own account.';else{$s=$db->prepare('UPDATE users SET is_active=IF(is_active=1,0,1) WHERE id=?');$s->bind_param('i',$id);$s->execute();audit($db,'USER_STATUS_TOGGLED','user',(string)$id,'Changed active status');$message='User status updated.';}}}
$users=$db->query('SELECT id,username,full_name,role,is_active,created_at FROM users ORDER BY id');
page_header('User management');echo '<h1>User management</h1>';if($message)echo '<div class="notice">'.h($message).'</div>';if($error)echo '<div class="notice error">'.h($error).'</div>';
echo '<div class="card"><h2>Create account</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="'.h(csrf_token()).'"><input type="hidden" name="action" value="create"><div><label>Full name</label><input name="full_name" required></div><div><label>Username</label><input name="username" required minlength="3" pattern="[A-Za-z0-9_.-]+"></div><div><label>Temporary password (12+ characters)</label><input type="password" name="password" required minlength="12" autocomplete="new-password"></div><div><label>Role</label><select name="role"><option value="viewer">Viewer (read only)</option><option value="hr">HR (manage employees)</option><option value="admin">Admin (all access)</option></select></div><div style="align-self:end"><button>Create user</button></div></form></div><div class="card"><h2>Accounts</h2><div class="table-wrap"><table><tr><th>Username</th><th>Name</th><th>Role</th><th>Status</th><th>Created</th><th class="no-print">Action</th></tr>';
while($u=$users->fetch_assoc()){echo '<tr><td>'.h($u['username']).'</td><td>'.h($u['full_name']).'</td><td>'.h($u['role']).'</td><td>'.((int)$u['is_active']?'Active':'Inactive').'</td><td>'.h($u['created_at']).'</td><td class="no-print">';if((int)$u['id']!==(int)$_SESSION['user_id'])echo '<form method="post"><input type="hidden" name="csrf" value="'.h(csrf_token()).'"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="'.(int)$u['id'].'"><button class="muted-btn">'.((int)$u['is_active']?'Deactivate':'Activate').'</button></form>';else echo 'Current account';echo '</td></tr>';}
echo '</table></div><p class="muted">Password reset is not included yet. To reset a password, use a reviewed administrator procedure and PHP password_hash().</p></div>';page_footer();